/** Every catalog entry, flattened (selector lookup by key). */
export const PACK_ENTRIES: readonly PackCatalogEntry[] =
  PACK_CATALOG.flatMap((lane) => lane.entries);

/**
 * Capability gaps recorded at build time — shown in the UI instead of being
 * quietly absent (e.g. why no CC0 animal head is grafted onto the mesh body).
 */
export const PACK_BLOCKED: readonly {
  readonly id: string;
  readonly wanted: string;
  readonly verdict: string;
  readonly evidence: string;
  readonly blocker: string;
  readonly shippedInstead: string;
}[] = [
  {
    "id": "polygonalmind-100avatars-atlas-recolor",
    "wanted": "Per-region recolour on the 100Avatars line.",
    "verdict": "NOT SHIPPED - but a measured, bounded route now exists; this is unbuilt work, not a dead end.",
    "evidence": "Four boundaries were measured across all 8 shipped avatars. (1) STRUCTURE gives nothing: 1 mesh node, 1 mesh, 1 PRIMITIVE, 1 material per file, and no COLOR_0 attribute. (2) VRM METADATA gives nothing: firstPerson.meshAnnotations empty on all 8 (not even the head is annotated), spring-bone groups empty, no blendShape materialValues, and the single materialProperties entry points _MainTex and _ShadeTexture at the SAME image. (3) BONE WEIGHT does split the mesh (jimmy: head 1411 / torso 123 / arm 864 / leg 142 vertices) but ANATOMICALLY: one head group carries face, hair and eyes together, and the groups share atlas texels heavily - as little as 2% of a group's texels are exclusive to it. (4) UV ISLANDS are a genuinely good boundary, which an earlier version of this entry wrongly denied existed: 94 large islands across the 8 avatars (median 12 each), 97% internally single-hue. They are also anatomical, though - those 94 islands carry only 23 distinct dominant colours between them (jimmy: 14 islands, 2 colours), so assigning a house region per island would repaint body parts rather than materials. THE SAME MEASUREMENT IS THE ROUTE: each avatar resolves to just 2-4 base colours (jimmy 2, cactusboy 2, mint 2, skelly 2, teddy 3, skull 4, froggy 4, polybot 4), and THAT is a material partition. A per-texel hue classifier - nearest of N baked hues -> house region - recolours these correctly with no mesh split and no extra texture. The two JPEG-textured avatars (froggy, polybot) are NOT excluded: being non-indexed blocks an index->region LUT, not hue classification.",
    "blocker": "Unbuilt, not impossible. It needs: a 23-row hue->region table in this file (the same shape as the materialPolicy slot maps, and smaller than the 39-row monsters map); house_toon_core's atlas branch generalised from ONE atlas_hue uniform to up to 4 (hue, region) pairs picking the nearest; and pack_mount binding one such material for the whole mesh. Everything else - the hue-selective tint, the luminance-preserving ramp, the shared-palette recolour path - already ships for the KayKit lines.",
    "shippedInstead": "The vendor material is preserved and the UI marks these entries 'fixed colours'. They are the BYO-VRM importer's reference corpus rather than player avatars, so the editor loses nothing while this is outstanding."
  },
  {
    "id": "oga-base-rigged-stylized-humanoid-yw",
    "wanted": "The CC0 'Base Rigged Stylized Humanoid Character (YW)' as a second anime base.",
    "verdict": "NOT VENDORED - the archive contains no format anything here can read.",
    "evidence": "The only geometry in the OGA archive is a .blend file — no FBX/glTF/DAE export exists.",
    "blocker": "Blender, or any other reader of the .blend format, and none is reachable here. .blend is a proprietary binary dump of Blender's in-memory structures; Godot cannot import it, GLTFDocument cannot parse it, and nothing in tools/asset-pipeline reads it. The usual escape hatch is the `bpy` PyPI wheel, which was checked rather than assumed: this machine has no pip at all and runs Python 3.14, for which no bpy wheel is published. Unlike the animal-head graft - where the data needed was already sitting in the GLB's bone weights - there is no alternative data path, because the geometry exists ONLY inside that one file.",
    "shippedInstead": "The two VRoid CC0 bases plus Godette cover the anime lane."
  }
] as const;
